DROP TABLE IF EXISTS t;
CREATE TABLE t(id INTEGER PRIMARY KEY,v,u INTEGER,w INTEGER);
CREATE UNIQUE INDEX tu ON t(u);
CREATE INDEX tw ON t(w);
INSERT INTO t VALUES(1,'a',1,3),(2,'b',2,2),(3,'c',3,1);
UPDATE OR IGNORE t SET u=100 WHERE u>0 AND w>0;
SELECT id FROM t WHERE u=100;

